{
  "name": "@skwid138/opencode-council",
  "version": "0.3.0",
  "description": "Multi-model adversarial review council plugin for opencode",
  "type": "module",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./server": {
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "LICENSE",
    "README.md"
  ],
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "test": "node test/run-isolated.mjs vitest run",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "verify:pack": "node test/run-isolated.mjs node test/verify-pack.mjs",
    "verify:consumer": "node test/run-isolated.mjs node test/verify-pack.mjs --consumer-types",
    "test:real-host": "node test/real-host/run.mjs",
    "prepublishOnly": "npm run build",
    "prepare": "husky || true"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.15.0"
  },
  "devDependencies": {
    "@commitlint/cli": "^21.0.2",
    "@commitlint/config-conventional": "^21.0.2",
    "@opencode-ai/plugin": "^1.15.0",
    "@opencode-ai/sdk": "^1.15.0",
    "@opencode/plugin": "2.0.32",
    "@types/node": "^22.0.0",
    "husky": "^9.1.7",
    "semantic-release": "^25.0.0",
    "typescript": "^6.0.3",
    "vitest": "^4.1.7"
  },
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/skwid138/opencode-council.git"
  },
  "homepage": "https://github.com/skwid138/opencode-council",
  "bugs": {
    "url": "https://github.com/skwid138/opencode-council/issues"
  },
  "license": "MIT",
  "keywords": [
    "opencode",
    "plugin",
    "council",
    "review",
    "multi-model",
    "opencode-plugin",
    "code-review",
    "adversarial-review",
    "multi-agent",
    "llm"
  ]
}
